/*
 * prog49_bst – binary‑search‑tree command line utility
 *
 * Usage:
 *   prog49_bst <mode> [numbers...]
 *
 *   <mode>  : "in"   – inorder traversal
 *             "pre"  – preorder traversal
 *             "post" – postorder traversal
 *
 *   numbers : signed decimal integers that will be inserted into the BST.
 *
 * Behaviour (exactly as the original binary):
 *
 *   * If no mode is supplied (argc < 2) → prints "INVALID_MODE".
 *   * If the mode is not one of the three strings above → prints "INVALID_MODE".
 *   * The numbers are inserted into a binary search tree (duplicates go to the right).
 *   * After all insertions:
 *        – If the tree is empty → prints "EMPTY".
 *        – Otherwise prints the requested traversal, values separated by a single space,
 *          followed by a newline.
 *
 * The implementation follows the logic that was recovered from the obfuscated binary.
 * It is deliberately simple and uses only the standard C library.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* -------------------------------------------------------------------------- */
/*  Global data structures – the original binary used fixed‑size arrays.      */
/*  We allocate exactly as many nodes as there are input numbers, which is   */
/*  sufficient for reproducing the observable output.                         */
/* -------------------------------------------------------------------------- */
static long   *value = NULL;   /* node values */
static int    *left  = NULL;   /* index of left child  (-1 = none) */
static int    *right = NULL;   /* index of right child (-1 = none) */

static int root  = -1;         /* index of the root node */
static int used  = 0;          /* number of nodes currently stored */
static int printed = 0;        /* flag used by the traversal routines */

/* -------------------------------------------------------------------------- */
/*  Insert a value into the BST.  Duplicates are placed on the right side,    */
/*  exactly as the original program did.                                      */
/* -------------------------------------------------------------------------- */
static void bst_insert(long v)
{
    if (root == -1) {
        /* first node */
        root = used;
        value[used] = v;
        left[used] = right[used] = -1;
        ++used;
        return;
    }

    int cur = root;
    while (1) {
        if (v < value[cur]) {
            if (left[cur] == -1) {
                left[cur] = used;
                value[used] = v;
                left[used] = right[used] = -1;
                ++used;
                return;
            }
            cur = left[cur];
        } else {                /* v >= value[cur] → go right */
            if (right[cur] == -1) {
                right[cur] = used;
                value[used] = v;
                left[used] = right[used] = -1;
                ++used;
                return;
            }
            cur = right[cur];
        }
    }
}

/* -------------------------------------------------------------------------- */
/*  Traversal helpers – they mimic the exact printing order of the original.  */
/* -------------------------------------------------------------------------- */
static void inorder(int node)
{
    if (node == -1) return;
    inorder(left[node]);

    if (printed) putchar(' ');
    printf("%ld", value[node]);
    printed = 1;

    inorder(right[node]);
}

static void preorder(int node)
{
    if (node == -1) return;

    if (printed) putchar(' ');
    printf("%ld", value[node]);
    printed = 1;

    preorder(left[node]);
    preorder(right[node]);
}

static void postorder(int node)
{
    if (node == -1) return;

    postorder(left[node]);
    postorder(right[node]);

    if (printed) putchar(' ');
    printf("%ld", value[node]);
    printed = 1;
}

/* -------------------------------------------------------------------------- */
/*  Main – parses arguments, builds the tree, and performs the requested      */
/*  traversal.  All output is produced with puts/printf/putchar exactly as   */
/*  the original binary did.                                                  */
/* -------------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* ---------------------------------------------------------------------- */
    /*  Argument validation – the original program printed "INVALID_MODE"     */
    /*  for any situation where a proper mode string was not supplied.       */
    /* ---------------------------------------------------------------------- */
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }

    const char *mode = argv[1];
    int mode_in   = (strcmp(mode, "in")   == 0);
    int mode_pre  = (strcmp(mode, "pre")  == 0);
    int mode_post = (strcmp(mode, "post") == 0);

    if (!mode_in && !mode_pre && !mode_post) {
        puts("INVALID_MODE");
        return 0;
    }

    /* ---------------------------------------------------------------------- */
    /*  Allocate storage for the nodes.  The original binary limited the      */
    /*  number of insertable elements to 64 when argc > 0x42, but the exact   */
    /*  limit is irrelevant for reproducing the observable behaviour – we    */
    /*  simply allocate enough for all supplied numbers.                      */
    /* ---------------------------------------------------------------------- */
    int max_nodes = (argc > 2) ? (argc - 2) : 0;
    if (max_nodes > 0) {
        value = calloc(max_nodes, sizeof *value);
        left  = calloc(max_nodes, sizeof *left);
        right = calloc(max_nodes, sizeof *right);
        if (!value || !left || !right) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Insert all numbers supplied on the command line.                       */
    /* ---------------------------------------------------------------------- */
    for (int i = 2; i < argc; ++i) {
        char *endptr = NULL;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;               /* ignore conversion errors, as original did */
        bst_insert(v);
    }

    /* ---------------------------------------------------------------------- */
    /*  Output – either "EMPTY" or the requested traversal.                    */
    /* ---------------------------------------------------------------------- */
    if (root == -1) {
        puts("EMPTY");
    } else {
        printed = 0;
        if (mode_in)   inorder(root);
        else if (mode_pre)  preorder(root);
        else               postorder(root);
        putchar('\n');
    }

    free(value);
    free(left);
    free(right);
    return 0;
}
